import{_ as t,H as s,f as r,i as a}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"23 | [视频]导读lua-resty-requests：优秀的lua-resty-*是如何编写的？","description":"","frontmatter":{},"headers":[{"level":2,"title":"今日核心","slug":"今日核心","link":"#今日核心","children":[]},{"level":2,"title":"课件参考","slug":"课件参考","link":"#课件参考","children":[]}],"relativePath":"OpenResty从入门到实战/23-［视频］导读lua-resty-requests：优秀的lua-resty-是如何编写的？.md","filePath":"OpenResty从入门到实战/23-［视频］导读lua-resty-requests：优秀的lua-resty-是如何编写的？.md","lastUpdated":null}'),l={name:"OpenResty从入门到实战/23-［视频］导读lua-resty-requests：优秀的lua-resty-是如何编写的？.md"};function u(i,e,_,p,n,o){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="_23-视频-导读lua-resty-requests-优秀的lua-resty-是如何编写的" tabindex="-1">23 | [视频]导读lua-resty-requests：优秀的lua-resty-*是如何编写的？ <a class="header-anchor" href="#_23-视频-导读lua-resty-requests-优秀的lua-resty-是如何编写的" aria-label="Permalink to &quot;23 | [视频]导读lua-resty-requests：优秀的lua-resty-*是如何编写的？&quot;">​</a></h1><p>你好，我是温铭。</p><p>今天的内容，我同样会以视频的形式来讲解。老规矩，在你进行视频学习之前，先问你这么几个问题：</p><ul><li>面对多个相同功能的 lua-resty 库，我们应该从哪些方面来选择？</li><li>如何来组织一个 lua-resty 的结构？</li></ul><p>这几个问题，也是今天视频课要解决的核心内容，希望你可以先自己思考一下，并带着问题来学习今天的视频内容。</p><p>同时，我会给出相应的文字介绍，方便你在听完视频内容后，及时总结与复习。下面是今天这节课的文字介绍部分。</p><h2 id="今日核心" tabindex="-1">今日核心 <a class="header-anchor" href="#今日核心" aria-label="Permalink to &quot;今日核心&quot;">​</a></h2><p>前面我们介绍过的 lua-resty 库都是官方自带的，但在 HTTP client 这个最常用的库上，官方并没有。这时候，我们就得自己来选择一个优秀的第三方库了。</p><p>那么，如何在众多的 lua-resty HTTP client 中，选择一个最好、最适合自己的第三方库呢？</p><p>这时候，你就需要综合考虑活跃度、作者、测试覆盖度、接口封装等各方面的因素了。我最后选择的是 lua-resty-requests（ <a href="https://github.com/tokers/lua-resty-requests" target="_blank" rel="noreferrer">https://github.com/tokers/lua-resty-requests</a>），它是由又拍云的工程师 tokers 贡献的，我个人很喜欢它的接口风格，也推荐给你。</p><p>在视频中我会从最简单的 get 接口入手，结合文档、测试案例和源码，来逐步展开。你可以看到一个优秀的 lua-resty 库是如何编写的，有哪些可以借鉴的地方。</p><h2 id="课件参考" tabindex="-1">课件参考 <a class="header-anchor" href="#课件参考" aria-label="Permalink to &quot;课件参考&quot;">​</a></h2><p>今天的课件已经上传到了我的GitHub上，你可以自己下载学习。</p><p>链接如下： <a href="https://github.com/iresty/geektime-slides" target="_blank" rel="noreferrer">https://github.com/iresty/geektime-slides</a></p><p>如果有不清楚的地方，你可以在留言区提问，另也可以在留言区分享你的学习心得。期待与你的对话，也欢迎你把这篇文章分享给你的同事、朋友，我们一起交流、一起进步。</p>',15)])])}const c=t(l,[["render",u]]);export{h as __pageData,c as default};
